using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Stock;
[Authorize]public sealed class IndexModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public string?Search{get;set;}[BindProperty(SupportsGet=true)]public string?Status{get;set;}public IReadOnlyList<StockItem>Items{get;private set;}=[];[TempData]public string?StatusMessage{get;set;}[TempData]public string?ErrorMessage{get;set;}public async Task OnGetAsync(CancellationToken ct){var today=DateTime.UtcNow.Date;var cutoff=today.AddDays(30);var q=db.StockBatches.AsNoTracking();if(!string.IsNullOrWhiteSpace(Search)){var s=Search.Trim();q=q.Where(x=>EF.Functions.Like(x.Medicine.Name,$"%{s}%")||EF.Functions.Like(x.BatchNumber,$"%{s}%"));}if(Status=="expired")q=q.Where(x=>x.ExpiryDate<today);else if(Status=="expiring")q=q.Where(x=>x.ExpiryDate>=today&&x.ExpiryDate<=cutoff);else if(Status=="usable")q=q.Where(x=>x.ExpiryDate>=today);Items=await q.OrderBy(x=>x.ExpiryDate).Select(x=>new StockItem(x.Id,x.Medicine.Name,x.BatchNumber,x.Quantity,x.ExpiryDate,x.Supplier.Name,x.ExpiryDate<today?"Expired":x.ExpiryDate<=cutoff?"Expiring soon":"Usable")).ToListAsync(ct);}
public async Task<Microsoft.AspNetCore.Mvc.IActionResult>OnPostDeleteAsync(int id,CancellationToken ct){var x=await db.StockBatches.SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null){ErrorMessage="Stock batch not found.";return RedirectToPage();}if(await db.SaleItems.AnyAsync(i=>i.StockBatchId==id,ct)||await db.StockAdjustments.AnyAsync(a=>a.StockBatchId==id,ct)||x.Quantity>0){ErrorMessage="Used stock records cannot be deleted. Use a stock quantity correction instead.";return RedirectToPage();}db.StockBatches.Remove(x);await db.SaveChangesAsync(ct);StatusMessage="Unused stock batch deleted.";return RedirectToPage();}}
public sealed record StockItem(int Id,string Medicine,string BatchNumber,int Quantity,System.DateTime ExpiryDate,string Supplier,string Status);
